#include "traffic/TrainingData.hpp"
#include <cmath>
#include <filesystem>
#include <iostream>
#include <stdexcept>
using namespace traffic;
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
bool near(double a,double b){return std::abs(a-b)<1e-7;}
int main(){try{
    TrafficLight west;west.id=1;west.a={100,0};west.b={100,20};west.outDirection={1,0};west.greenSeconds=1;west.yellowSeconds=1;west.redSeconds=1000;west.offsetSeconds=2;
    auto north=west;north.id=2;north.a={200,200};north.b={220,200};north.outDirection={0,1};std::vector<TrafficLight> lights{west,north};auto regions=defaultSignalRegions(lights);
    Entity a;a.id=10;a.center={95,5};a.length=4;a.width=2;a.heading=0;a.speed=0;auto b=a;b.id=20;b.center={75,10};auto unseen=a;unseen.id=30;unseen.center={5,10};auto incoming=a;incoming.id=40;incoming.heading=3.141592653589793;
    QueueConfig config;config.horizon=80;config.shortLimit=10;config.moderateLimit=40;SignalWaitTracker tracker;
    tracker.update(lights,{a,b,unseen,incoming},regions,0,config);tracker.update(lights,{a,b,unseen,incoming},regions,1,config);
    auto q=tracker.snapshot().groups[0];require(q.vehicles==2 && near(q.metres,27) && q.category==2,"Visible metre queue or direction/range filtering is wrong");require(near(q.wait.minimum,1) && near(q.wait.maximum,1),"First stop interval was not tracked");
    a.speed=2;a.center.x=96;tracker.update(lights,{a,b},regions,2,config);q=tracker.snapshot().groups[0];require(near(q.wait.minimum,1) && near(q.wait.maximum,2) && near(q.wait.median,1.5) && near(q.wait.mean,1.5),"Rolling vehicle lost its accumulated wait");
    a.speed=0;a.center.x=97;tracker.update(lights,{a,b},regions,3,config);require(near(tracker.snapshot().groups[0].wait.minimum,2),"A second stop reset the signal wait");
    a.center.x=103;a.speed=2;tracker.update(lights,{a,b},regions,4,config);auto completed=tracker.takeCompleted();require(completed.size()==1 && completed[0].outcome=="crossed" && near(completed[0].wait,2) && completed[0].bursts==2,"Crossing did not finalize the two-burst wait episode");require(tracker.snapshot().groups[0].wait.count==1,"Crossed vehicles remain in active wait statistics");
    auto edge=b;edge.id=50;edge.center.x=21;tracker.update(lights,{b,edge},regions,5,config);q=tracker.snapshot().groups[0];require(q.cameraLimit && near(q.metres,80),"Partially visible camera-edge queue was not capped");
    tracker.finish(6,"reset");completed=tracker.takeCompleted();require(completed.size()==2 && completed[0].outcome=="reset","Uncrossed waits were not censored at reset");
    HoldSignalController hold;auto original=lights;hold.begin(lights,regions,0,10,2,1,1);hold.update(lights,1);require(near(hold.countdown(0,1),2),"Tr did not start after yellow");require(lights[0].phase(1)==LightPhase::Red && lights[1].phase(1)==LightPhase::Red,"Tr is not an all-red interval");hold.update(lights,3);require(hold.greenGroup()==0,"Initial green released before/after the Tr deadline");
    hold.request(-1);hold.update(lights,10);require(hold.greenGroup()==0,"Hold unexpectedly used a fixed green cycle");hold.update(lights,11);require(hold.forced() && lights[0].phase(11)==LightPhase::Yellow,"Maximum-red limit did not force yellow");hold.request(0);hold.update(lights,12);require(near(hold.countdown(1,12),2) && lights[0].phase(12)==LightPhase::Red,"Forced transition skipped the final Tr");hold.request(-1);hold.update(lights,13);require(near(hold.countdown(1,13),1),"A request cancelled or restarted Tr");hold.update(lights,14);require(hold.greenGroup()==1,"Waiting group did not get green after Tr");
    for(int i=141;i<400;++i){double t=i*.1;hold.update(lights,t);require(!(lights[0].phase(t)==LightPhase::Green && lights[1].phase(t)==LightPhase::Green),"Conflicting greens during forced hold switching");}hold.stop(lights);require(near(lights[0].offsetSeconds,original[0].offsetSeconds),"Manual timing did not restore");
    HoldSignalController coarse;coarse.begin(lights,regions,0,10,2,1,1);coarse.update(lights,1.7);require(near(coarse.countdown(0,1.7),2),"A late physics step shortened the start of Tr");coarse.update(lights,3.1);require(coarse.greenGroup()==-1,"Green was released before a full actual Tr elapsed");coarse.update(lights,3.7);require(coarse.greenGroup()==0,"Coarse-step clearance did not release green");coarse.stop(lights);
    HoldSignalController longHold;longHold.begin(lights,regions,0,3600,100,20,5);longHold.update(lights,20);longHold.update(lights,120);longHold.update(lights,3620);longHold.update(lights,3640);require(lights[0].phase(3700)==LightPhase::Red && lights[1].phase(3700)==LightPhase::Red,"Held red escaped through the underlying cyclic timer");longHold.update(lights,3740);require(longHold.greenGroup()==1,"Long held red did not finish its forced clearance");longHold.stop(lights);
    DemandConfig demandConfig;demandConfig.seed=19;demandConfig.minimum=.3;demandConfig.maximum=1.2;demandConfig.changeMin=1;demandConfig.changeMax=3;demandConfig.zeroProbability=.2;
    RandomDemand first,second;std::vector<DemandSource> sources{{1,.5},{2,.5}};first.begin(sources,demandConfig);second.begin(sources,demandConfig);int arrivals=0;bool distinct=false;
    for(int tick=0;tick<1000;++tick){double t=tick*.1;first.update(t);second.update(t);for(int node:{1,2}){while(true){bool x=first.due(node,t),y=second.due(node,t);require(x==y,"Seeded arrival replay differs");if(!x)break;++arrivals;}}auto& rates=first.sources();distinct=distinct || rates[0].rate!=rates[1].rate;for(auto& source:rates)require(source.rate==0 || (source.rate>=.3 && source.rate<=1.2),"Random rate left its configured bounds");}
    require(arrivals>20 && distinct,"Demand is not independently randomized across nodes");
    auto dir=std::filesystem::temp_directory_path()/("traffic-training-test-"+std::to_string(std::random_device{}()));TrainingRecorder recorder;recorder.open(dir.u8string(),19,config,demandConfig,10,2,1,0);recorder.sample(tracker.snapshot());recorder.waits(completed);recorder.demand(first.takeEvents());auto before=tracker.snapshot(),after=before;after.time+=1;after.totalWait+=3;after.totalWaitByGroup[0]+=3;recorder.transition(before,-1,after,true,false);recorder.close();require(std::filesystem::file_size(dir/"transitions.jsonl")>100,"Training transitions were not exported");bool refused=false;try{recorder.open(dir.u8string(),19,config,demandConfig,10,2,1,0);}catch(...){refused=true;}require(refused,"Existing datasets can be overwritten");
    std::cout<<"Camera-limited queues, cumulative stop bursts, wait quantiles, Tr clearance, forced red limits, randomized seeded demand and dataset export passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
